window.COURSES = window.COURSES || []; window.TIPS = window.TIPS || [];
window.COURSES.push(
{ id:"mo01", cat:"money", e:"🧾", title:"Budgeting That Actually Works", sub:"Control your cash without misery", cards:[
 {e:"🔍", h:"Know Where Money Goes", t:"A budget starts with facts, not willpower. Pull three months of bank and card statements and total what you really spent by category. Most people discover a few surprises, usually subscriptions, food delivery, or small daily purchases that add up."},
 {e:"🍰", h:"The 50/30/20 Guideline", t:"A popular starting point splits after-tax income into needs, wants, and savings or debt payoff. It is a rule of thumb, not a law. If rent is high where you live, adjust the ratios and keep the habit.", stat:{n:"50/30/20", l:"needs / wants / savings split suggested by Elizabeth Warren"}},
 {e:"💸", h:"Pay Yourself First", t:"Instead of saving whatever is left over, move money into savings the day you get paid. Automatic transfers remove the daily decision. What remains is your spending money, and you stop needing willpower to save."},
 {e:"📋", h:"Zero-Based Budgeting", t:"Give every dollar of income a job until income minus planned spending equals zero. Savings and debt payments count as jobs. This method works well for people who like detail and want to see exactly where each paycheck goes.", list:["List your monthly income","List fixed bills first","Assign savings and debt goals","Spend the rest on flexible categories"]},
 {e:"🔁", h:"Fixed vs Variable Costs", t:"Rent, insurance, and loan payments are fixed and hard to change quickly. Groceries, fun, and clothing are variable and easy to adjust. When money is tight, trim variable costs first, then negotiate or reduce fixed ones for lasting impact."},
 {e:"📅", h:"Plan Irregular Expenses", t:"Annual insurance, car repairs, gifts, and holidays wreck budgets because they feel like surprises. They are predictable. Divide the yearly total by twelve and set that amount aside monthly in a separate sinking fund."},
 {e:"🛑", h:"Beware Lifestyle Creep", t:"When income rises, spending quietly rises to match it. A raise that turns into a bigger apartment and nicer car leaves your savings unchanged. Decide in advance to save at least half of any future raise.", stat:{n:"50%", l:"of a raise saved is a common rule of thumb, not a requirement"}},
 {e:"🗓️", h:"Review Monthly, Not Daily", t:"Checking every purchase burns you out. Set one short monthly money meeting: compare actual to planned, fix one leak, adjust next month. Consistency beats perfection, and a budget that is too strict gets abandoned. This is general education, not personal advice."}
], quiz:[
 {q:"What is the best first step when building a budget?", o:["Cut all fun spending","Review past statements to see real spending","Open an investment account"], a:1, w:"You cannot plan well until you know what you actually spend."},
 {q:"What does 'pay yourself first' mean?", o:["Spend on yourself before bills","Buy rewards before saving","Automatically save when you are paid"], a:2, w:"Automating savings at payday makes saving the default instead of leftovers."},
 {q:"How should you handle annual insurance bills in a budget?", o:["Save a monthly share in a sinking fund","Ignore them until they arrive","Put them on a credit card"], a:0, w:"Dividing a predictable yearly cost by twelve prevents surprise shortfalls."},
 {q:"What is lifestyle creep?", o:["Spending rising as income rises","Lowering costs after a pay cut","Moving to a cheaper city"], a:0, w:"Spending that grows with income stops raises from increasing savings."}
]},
{ id:"mo02", cat:"money", e:"🛟", title:"Emergency Funds and Saving", sub:"Build your financial shock absorber", cards:[
 {e:"🌧️", h:"Why Emergency Funds Matter", t:"Job loss, medical bills, and car repairs arrive without warning. Without savings, these events land on credit cards and loans at high interest. A cash cushion turns a crisis into an inconvenience and protects your long-term plans."},
 {e:"🎯", h:"How Much to Save", t:"A common guideline is three to six months of essential expenses, not income. Count rent, food, utilities, insurance, and minimum debt payments. People with unstable income or dependents often aim higher.", stat:{n:"3-6 mo", l:"of essential expenses is the usual emergency fund guideline"}},
 {e:"🥾", h:"Start With a Small Goal", t:"A target of six months can feel hopeless. Begin with one thousand dollars or one month of expenses. Hitting a small goal builds momentum, and even that amount covers many common surprises like a flat tire or a vet bill."},
 {e:"🏦", h:"Where to Keep It", t:"Use a separate, easy-to-access savings account, ideally high-yield and insured by your national deposit protection program. Do not invest it in stocks, since the fund must hold its value exactly when markets and jobs are shaky."},
 {e:"🤖", h:"Automate the Habit", t:"Set a recurring transfer on payday, even a modest amount. Automatic saving works because it removes the choice. Raise the amount whenever your income or bills change, and let windfalls like tax refunds top it up faster.", list:["Open a separate account","Set an automatic transfer","Raise it with each raise","Add windfalls like refunds"]},
 {e:"🚨", h:"What Counts as an Emergency", t:"A true emergency is unexpected, necessary, and urgent: job loss, medical bills, essential repairs. A sale or a vacation is not one. Writing your own definition in advance stops the fund from being drained by temptation."},
 {e:"🔄", h:"Refill After Using It", t:"Using the fund is exactly what it is for, so do not feel guilty. Just make rebuilding it a priority afterward, before returning to extra investing or large discretionary spending. Treat it like replacing a spare tire."},
 {e:"🎈", h:"Sinking Funds for Goals", t:"Beyond emergencies, save for known goals in separate buckets: a car, travel, a home down payment. Naming each account makes progress visible and reduces dipping into the wrong money. This is general education, not personal financial advice."}
], quiz:[
 {q:"What should an emergency fund be based on?", o:["Your total gross income","Your essential expenses","Your highest monthly bill"], a:1, w:"The fund replaces needed spending during a crisis, so essentials set the target."},
 {q:"Where is the best place for emergency savings?", o:["Volatile stocks","A locked long-term investment","An accessible insured savings account"], a:2, w:"It must be safe and quickly available when you need it."},
 {q:"Which of these is a real emergency?", o:["Unexpected job loss","A big sale on a TV","A friend's weekend trip"], a:0, w:"Emergencies are unexpected, necessary and urgent, like losing income."},
 {q:"What should you do after using your emergency fund?", o:["Forget about it","Rebuild it as a priority","Close the account"], a:1, w:"Replenishing it restores your protection against the next shock."}
]},
{ id:"mo03", cat:"money", e:"💳", title:"Debt and Credit Scores", sub:"Borrow smart, escape faster", cards:[
 {e:"⚖️", h:"Good Debt vs Bad Debt", t:"Debt is a tool with a cost. Borrowing at a low rate to build something valuable, like education or a reasonable mortgage, can make sense. High-interest debt for consumption, like card balances, usually drains your wealth."},
 {e:"📈", h:"How Interest Bites", t:"Credit card interest often runs around twenty percent a year or more. Paying only the minimum can stretch a small balance over many years and cost more than the purchase itself. Always check the APR before borrowing.", stat:{n:"~20%", l:"typical credit card APR range in the US"}},
 {e:"⛰️", h:"Avalanche Method", t:"List debts by interest rate and pay minimums on all, then throw every extra dollar at the highest-rate debt. When it is gone, roll that payment to the next one. Mathematically, this saves the most interest."},
 {e:"⛄", h:"Snowball Method", t:"Pay the smallest balance first regardless of rate, then roll its payment to the next smallest. It costs a little more interest, but quick wins build motivation. The best method is the one you will stick with."},
 {e:"🔢", h:"What Makes a Credit Score", t:"In the US, scores weigh payment history most, then how much of your available credit you use, then length of history, new accounts, and mix of credit. Pay on time and keep card use well below the limit.", list:["Pay every bill on time","Keep utilization under 30%","Avoid opening many accounts","Keep old accounts open"]},
 {e:"🛑", h:"Utilization Matters", t:"Utilization is your balance divided by your credit limit. Using ninety percent of a limit looks risky to lenders, even if you pay in full later. Paying before the statement date or asking for a higher limit can lower it.", stat:{n:"30%", l:"common rule of thumb for a maximum card utilization"}},
 {e:"📝", h:"Check Your Reports", t:"Errors on credit reports happen and can raise your borrowing costs. In the US you can request free reports from each major bureau through the official site annualcreditreport.com. Dispute mistakes in writing and keep copies."},
 {e:"🏃", h:"Do Not Chase Quick Fixes", t:"Credit repair companies cannot legally remove accurate negative information, and many charge upfront fees. Time and on-time payments are the real fix. If overwhelmed, nonprofit credit counseling can help. This is general education only."}
], quiz:[
 {q:"What does the avalanche method target first?", o:["Smallest balance","Highest interest rate","Oldest debt"], a:1, w:"Paying the highest-rate debt first minimizes total interest paid."},
 {q:"What most affects a US credit score?", o:["Your salary","Payment history","Your age"], a:1, w:"Payment history is the largest factor in common scoring models."},
 {q:"What is credit utilization?", o:["Balance compared to credit limit","Number of cards owned","Years of credit history"], a:0, w:"Utilization is balance divided by limit, and lower is better for scores."},
 {q:"Can credit repair firms remove accurate negative marks?", o:["Yes, for a fee","Only in some states","No, accurate items stay for their time"], a:2, w:"Accurate information stays until it ages off the report."}
]},
{ id:"mo04", cat:"money", e:"❄️", title:"The Power of Compounding", sub:"Why starting early beats starting big", cards:[
 {e:"🌱", h:"Interest on Interest", t:"Compounding means your earnings start earning their own earnings. Each year's growth is added to the base, so the next year's growth is larger. The curve starts slow and then steepens dramatically over decades."},
 {e:"⏳", h:"Time Is the Key Input", t:"Because growth builds on growth, extra years matter more than extra dollars. Someone who invests modestly at twenty-five can end up with more than someone who invests larger amounts starting at thirty-five, assuming similar returns."},
 {e:"🧮", h:"Rule of 72", t:"Divide 72 by an annual growth rate to estimate years to double your money. At 6 percent, money doubles in about twelve years. At 3 percent, about twenty-four. It is a quick mental shortcut, not an exact figure.", stat:{n:"72", l:"divided by the rate gives approximate years to double"}},
 {e:"📊", h:"An Illustration", t:"Investing 300 dollars a month at an assumed 6 percent yearly return grows to roughly 300,000 dollars over thirty-five years, though only about 126,000 is your own contributions. Returns are never guaranteed, so treat this as an example."},
 {e:"🔻", h:"Fees Compound Too", t:"A fund charging 1 percent a year versus 0.1 percent sounds trivial. Over thirty years, that gap can consume a fifth or more of your final balance. Low costs are one of the few things investors actually control."},
 {e:"💳", h:"Compounding Works Against You", t:"The same math that grows savings grows debt. Unpaid credit card interest is added to your balance and then charged interest itself. This is why paying high-interest debt is like earning a guaranteed return equal to its rate."},
 {e:"🔥", h:"Do Not Interrupt It", t:"Withdrawing early or selling in panic resets the curve. Staying invested through downturns lets compounding continue. Even small contributions made consistently, with dividends reinvested, outperform sporadic large moves for most people.", list:["Start as early as possible","Contribute automatically","Keep costs low","Avoid panic selling"]},
 {e:"🎬", h:"Patience Is the Strategy", t:"Compounding is boring because its benefits arrive late. Most of the final balance accumulates in the last years. The practical lesson: begin now, stay consistent, and let time work. This is general education, not a promise of returns."}
], quiz:[
 {q:"What is compounding?", o:["Earning interest on prior interest","Adding fees to a loan","Investing in many funds"], a:0, w:"Compounding means gains themselves generate further gains."},
 {q:"At a 6 percent return, about how long to double money?", o:["6 years","12 years","24 years"], a:1, w:"The Rule of 72 gives 72 divided by 6, which equals 12 years."},
 {q:"Why do fees matter so much over decades?", o:["They are always illegal","They only apply at the end","They compound against your balance"], a:2, w:"Fees reduce the base that would otherwise keep growing."},
 {q:"Which factor matters most in compounding?", o:["Time","Luck","Market timing"], a:0, w:"More years allow growth on growth to accumulate substantially."}
]},
{ id:"mo05", cat:"money", e:"🧺", title:"Index Funds and Diversification", sub:"Own the market, not a gamble", cards:[
 {e:"🥚", h:"Do Not Use One Basket", t:"Diversification means spreading money across many assets so no single failure ruins you. If one company collapses, it should be a small part of your total. It is the closest thing to a free lunch in investing."},
 {e:"📚", h:"What Is an Index Fund", t:"An index fund holds all the stocks in a market index, like the S&P 500, in proportion to their size. You own a tiny slice of hundreds of companies in one purchase, with very little trading and very low costs."},
 {e:"🏆", h:"Most Pros Underperform", t:"Over long periods, the majority of actively managed funds trail their benchmark index after fees. Beating the market consistently is extremely hard, which is why many experts suggest low-cost index funds for most people.", stat:{n:"~85-90%", l:"of US large-cap active funds trailed the S&P 500 over 15 years (SPIVA reports)"}},
 {e:"💰", h:"Expense Ratios", t:"The expense ratio is the yearly fee a fund takes as a percentage of your money. Many broad index funds charge under 0.1 percent, while some active funds charge over 1 percent. Compare this number before buying anything."},
 {e:"⚖️", h:"Stocks and Bonds Mix", t:"Stocks offer higher expected growth with bigger swings. Bonds are steadier with lower expected returns. Your mix should reflect your time horizon and how well you tolerate seeing balances drop, not predictions about the market."},
 {e:"🌍", h:"Geographic Spread", t:"Holding companies from many countries reduces dependence on one economy. Total-world or international funds provide this. Opinions differ on how much foreign exposure is ideal, but owning only one country is a concentrated bet."},
 {e:"🔧", h:"Rebalance Occasionally", t:"Over time, winners grow and your mix drifts from your target. Rebalancing once a year, or when it drifts by a set amount, brings it back. It enforces a habit of trimming what rose and adding to what lagged.", list:["Pick a target mix","Check once a year","Sell a bit of winners","Buy a bit of laggards"]},
 {e:"🧘", h:"Keep It Boring", t:"Chasing hot sectors and timing the market usually backfires through poor timing and extra costs. A simple, diversified, low-cost plan you can maintain through crashes tends to beat clever plans you abandon. General education only, not investment advice."}
], quiz:[
 {q:"What is diversification?", o:["Buying one great stock","Spreading money across many assets","Selling during drops"], a:1, w:"Spreading risk means one failure cannot sink your whole portfolio."},
 {q:"What does an expense ratio measure?", o:["A stock's growth","Annual fund fee as a percentage","Your tax rate"], a:1, w:"It is the yearly cost of holding the fund, taken from assets."},
 {q:"Why do many experts favor broad index funds?", o:["They guarantee profits","They are exempt from losses","Low cost and hard-to-beat market returns"], a:2, w:"Low fees plus broad exposure beat most active managers over time."},
 {q:"What is rebalancing?", o:["Returning to your target asset mix","Selling everything","Changing brokers"], a:0, w:"Rebalancing restores the risk level you originally chose."}
]},
{ id:"mo06", cat:"money", e:"🏖️", title:"Retirement Accounts Explained", sub:"401(k), IRA and tax-advantaged saving", cards:[
 {e:"🧓", h:"Why Retirement Accounts Exist", t:"Governments offer tax advantages to encourage long-term saving. Using these accounts can reduce what you owe in taxes today or later, which boosts what you keep. Rules vary by country, so check your local system."},
 {e:"🏢", h:"Employer Plans", t:"In the US, a 401(k) lets you contribute from your paycheck, often with investment options chosen by your employer. Contributions are usually pre-tax, lowering your taxable income now, with taxes due when you withdraw in retirement."},
 {e:"🎁", h:"Never Skip the Match", t:"Many employers match a portion of your contributions, for example 50 cents per dollar up to a limit. That is an immediate return on your money that is hard to beat anywhere else. Capture the full match before other investing.", stat:{n:"100%", l:"instant return on matched dollars when an employer matches dollar for dollar"}},
 {e:"🔀", h:"Traditional vs Roth", t:"Traditional accounts give a tax break now and tax withdrawals later. Roth accounts use after-tax money, but qualified withdrawals are tax-free. A Roth often suits those who expect higher future tax rates; a traditional suits the opposite."},
 {e:"👤", h:"Individual Accounts (IRA)", t:"An IRA is an account you open yourself, outside your employer. It offers extra choice and often lower fees. Annual contribution limits apply and change over time, so check the current numbers on the tax authority's site."},
 {e:"🚧", h:"Early Withdrawal Costs", t:"Taking money out of most retirement accounts before about age 59 and a half usually triggers taxes plus a ten percent penalty in the US, with some exceptions. Treat these accounts as locked, and keep emergency savings separately."},
 {e:"📆", h:"Vesting and Rollovers", t:"Employer matches may vest over time, meaning you earn them by staying a set number of years. When changing jobs, roll your old balance into a new plan or an IRA directly. Avoid cashing out, which triggers taxes and penalties.", list:["Check your vesting schedule","Roll over, do not cash out","Choose direct transfers","Keep records of accounts"]},
 {e:"🎯", h:"How Much to Save", t:"Common guidance suggests saving around 15 percent of gross income for retirement, including any employer match, starting early. Your ideal figure depends on age, goals, and benefits. Start with what you can and increase yearly. This is general education, not advice."}
], quiz:[
 {q:"What is an employer match?", o:["Extra money the employer adds to your contributions","A loan from your boss","A tax penalty"], a:0, w:"A match adds employer money when you contribute, like instant return."},
 {q:"How are qualified Roth withdrawals taxed?", o:["Double taxed","Tax-free","Taxed as a bonus"], a:1, w:"Roth contributions are after-tax, so qualified withdrawals are tax-free."},
 {q:"What happens with early retirement withdrawals in the US?", o:["Nothing","A bonus is paid","Usually taxes plus a penalty"], a:2, w:"Withdrawing before about 59 and a half generally brings a 10 percent penalty."},
 {q:"What should you usually do with an old 401(k) when changing jobs?", o:["Roll it over","Cash it out","Ignore it forever"], a:0, w:"Rolling over avoids taxes and penalties while keeping the money invested."}
]},
{ id:"mo07", cat:"money", e:"🧮", title:"Taxes Basics", sub:"Understand what you owe and why", cards:[
 {e:"🏛️", h:"What Taxes Fund", t:"Taxes pay for public services like roads, schools, defense, and social programs. Common types include income tax on earnings, sales tax on purchases, property tax on real estate, and payroll tax for social insurance."},
 {e:"📶", h:"Marginal Tax Brackets", t:"In progressive systems, only the portion of income within each bracket is taxed at that bracket's rate. A raise never lowers your take-home pay by pushing you into a higher bracket. Only the extra income is taxed more.", stat:{n:"Only the slice", l:"above a bracket threshold is taxed at the higher rate"}},
 {e:"🧾", h:"Gross vs Net Pay", t:"Gross pay is your salary before deductions. Net pay is what lands in your account after income tax, payroll tax, and benefits. Always compare job offers using estimated net pay and benefits, not just the headline salary."},
 {e:"✂️", h:"Deductions vs Credits", t:"A deduction reduces the income that is taxed. A credit reduces the tax itself, dollar for dollar. A 1,000 dollar credit is typically worth more than a 1,000 dollar deduction, which only saves your marginal rate percentage."},
 {e:"📈", h:"Capital Gains", t:"Profit from selling an investment is taxed as a capital gain. In the US, assets held more than a year usually receive lower long-term rates than short-term gains. Holding longer can legally reduce your bill. Rules differ by country."},
 {e:"🛡️", h:"Use Tax-Advantaged Accounts", t:"Retirement accounts and health savings accounts can lower taxes legally. Contributing to them is one of the simplest tax strategies available to ordinary people, and it requires no loopholes or complexity.", list:["Retirement accounts","Health savings accounts","Education savings plans","Employer benefits"]},
 {e:"📁", h:"Keep Good Records", t:"Save receipts, income statements, and records of deductions for several years, as many tax authorities allow audits for at least three years back. Digital folders by year make filing faster and protect you if questions arise."},
 {e:"👩‍⚖️", h:"Avoid Evasion, Use Planning", t:"Tax avoidance means legally reducing taxes; evasion means hiding income and is a crime. If your situation is complex, such as self-employment, a licensed tax professional can pay for themselves. This is general education, not tax advice."}
], quiz:[
 {q:"Can a raise reduce take-home pay by entering a higher bracket?", o:["Yes, always","No, only the extra income is taxed higher","Only in January"], a:1, w:"Marginal rates apply only to income within each bracket."},
 {q:"Which is generally more valuable, a 1,000 credit or 1,000 deduction?", o:["The deduction","They are identical","The credit"], a:2, w:"A credit cuts tax directly, while a deduction only reduces taxable income."},
 {q:"What is gross pay?", o:["Pay before deductions","Pay after taxes","Only bonus pay"], a:0, w:"Gross is the total earned before taxes and benefits are taken out."},
 {q:"What separates tax avoidance from evasion?", o:["The amount saved","Legality: avoidance is legal, evasion is not","The country"], a:1, w:"Avoidance uses legal rules, while evasion involves hiding income."}
]},
{ id:"mo08", cat:"money", e:"🤝", title:"Negotiating Your Salary", sub:"Ask well and earn what you are worth", cards:[
 {e:"🎤", h:"Always Negotiate", t:"Many employers expect a counteroffer and have room built into the initial number. Politely asking rarely costs you the job, while staying silent can lock in a lower salary that compounds across every future raise."},
 {e:"🔬", h:"Research Your Market Value", t:"Before talking numbers, find ranges for your role, location, and experience using salary sites, job postings in regions where pay disclosure is required, and professional contacts. A grounded number is far more persuasive than a guess."},
 {e:"⏱️", h:"Let Them Name It First", t:"If asked early about expectations, deflect politely: you would like to learn more about the role and are confident you can agree on fair pay. Revealing your number first can anchor the conversation too low."},
 {e:"⚓", h:"Anchor With a Range", t:"When you do state a number, start slightly above your target so the final result lands where you want it. A range with your ideal at the bottom lets them settle near it, so set the bottom at something you would accept.", stat:{n:"Aim high", l:"first numbers anchor the whole negotiation in research on anchoring"}},
 {e:"💬", h:"Frame Value, Not Need", t:"Talk about what you will deliver, not what you need to pay rent. Mention results, skills, and market data. Phrases like 'based on my research and the impact I can have, I am looking for' keep things collaborative.", list:["State market data","Cite your achievements","Ask a clear number","Stay friendly and calm"]},
 {e:"🎁", h:"Look Beyond Salary", t:"If base pay is capped, negotiate other items: signing bonus, extra vacation, remote days, equity, education budget, or an early review. Total compensation includes retirement match, insurance, and flexibility, which can be worth thousands."},
 {e:"🤫", h:"Silence Is a Tool", t:"After stating your number, stop talking. People often fill silence by conceding. Pause comfortably and let them respond. Practice aloud beforehand with a friend so your voice sounds steady and unapologetic."},
 {e:"📝", h:"Get It in Writing", t:"Once you agree, ask for the final terms in a written offer before resigning from your current role. For existing jobs, request raises with evidence in a dedicated meeting, not in passing. General education, not legal or career advice."}
], quiz:[
 {q:"What is a good way to respond if asked your salary expectation too early?", o:["Give a very low number","Refuse to ever discuss money","Deflect politely and learn about the role first"], a:2, w:"Naming a number first can anchor the negotiation against you."},
 {q:"What should you emphasize when negotiating?", o:["Your personal expenses","Value you bring and market data","Complaints about coworkers"], a:1, w:"Employers pay for results, so frame the case around value."},
 {q:"If the base salary cannot move, what else could you negotiate?", o:["Signing bonus, vacation or flexibility","Nothing at all","Only your job title"], a:0, w:"Total compensation has many components beyond base pay."},
 {q:"When should you get the final terms in writing?", o:["Never","After your first day","Before resigning from your current job"], a:2, w:"A written offer protects you before you make irreversible moves."}
]},
{ id:"mo09", cat:"money", e:"🧠", title:"Psychology of Money", sub:"Behavior beats spreadsheets", cards:[
 {e:"📖", h:"Behavior Over Intelligence", t:"Morgan Housel's core idea is that doing well with money depends more on behavior than on knowledge. A smart person who panics in a crash can lose more than an average person who calmly holds on."},
 {e:"🔄", h:"Everyone Has Their Own History", t:"People raised in different eras and families form different beliefs about risk and spending. Someone who lived through a recession may avoid stocks forever. Their choices are not stupid, just based on experience you did not have."},
 {e:"🎲", h:"Luck and Risk Are Real", t:"Success is never fully skill, and failure is never fully bad decisions. Both luck and risk shape outcomes. Be cautious about copying famous winners, and kinder when judging those whose bets failed."},
 {e:"🙅", h:"Know What Is Enough", t:"Chasing more without a stopping point is dangerous. People with a lot have lost everything by risking what they had and needed for what they did not need. Define enough, and then protect it above all."},
 {e:"🌊", h:"Get Wealthy, Stay Wealthy", t:"Getting rich takes taking risks; staying rich takes humility and frugality, and fear of losing it all. Survival matters because compounding needs time. Avoid any single bet that can wipe you out.", stat:{n:"Survival", l:"is the prerequisite for compounding to work"}},
 {e:"🛡️", h:"Room for Error", t:"Because the future is uncertain, build margin of safety: save more than your model says, hold cash, avoid overleveraging. Plans that only work if everything goes right are fragile, no matter how smart the math looks."},
 {e:"🎭", h:"Wealth Is What You Do Not See", t:"A fancy car shows spending, not wealth. Real wealth is the assets you did not spend. Being rich is visible; being wealthy is the money you kept, which gives options and freedom to control your own time."},
 {e:"⏰", h:"Time Freedom", t:"Housel argues the highest dividend of money is control over your time: choosing your work, hours, and projects. Saving without a specific goal is fine, because flexibility is the goal. Summary in my own words, general education only."}
], quiz:[
 {q:"According to Housel, what matters most with money?", o:["Behavior","Math degrees","Insider tips"], a:0, w:"The book argues behavior outweighs raw financial knowledge."},
 {q:"What does 'wealth is what you do not see' mean?", o:["Hide all money offshore","Visible spending is not wealth","Wealth is imaginary"], a:1, w:"Wealth is unspent assets, not the visible luxuries people buy."},
 {q:"Why build a margin of safety?", o:["To impress friends","Because spreadsheets are perfect","Because the future is uncertain"], a:2, w:"Uncertainty means plans must survive things going wrong."},
 {q:"What is described as money's highest dividend?", o:["Control over your time","A bigger house","Social status"], a:0, w:"Housel stresses autonomy over your own schedule as the top benefit."}
]},
{ id:"mo10", cat:"money", e:"🏠", title:"Rich Dad Poor Dad Lessons", sub:"Assets, liabilities and mindset", cards:[
 {e:"📕", h:"The Book in Brief", t:"Robert Kiyosaki's 1997 book contrasts two father figures: one with high education but little wealth, one a businessman with a different view of money. It popularized simple ideas about assets, income, and financial education."},
 {e:"🔑", h:"Assets vs Liabilities", t:"Kiyosaki defines assets as things that put money in your pocket and liabilities as things that take it out. By his definition, a primary home often counts as a liability because of mortgage, taxes, and upkeep. Many economists disagree.", stat:{n:"1997", l:"year Rich Dad Poor Dad was first published"}},
 {e:"🛒", h:"Buy Assets, Not Stuff", t:"The practical lesson: before buying something, ask whether it will produce income or only drain it. Spending on a gadget is fine, but be honest that it is consumption, not investment, and plan accordingly."},
 {e:"🐀", h:"Escaping the Rat Race", t:"The book describes people working for a paycheck, spending it all, then needing more pay. The suggested exit is building income-producing assets until their income covers your expenses, giving you choice instead of dependence."},
 {e:"🎓", h:"Financial Education Matters", t:"Kiyosaki criticizes schools for not teaching money skills. Whatever you think of his claims, the point stands: reading, taking courses, and learning accounting basics pay off for life, since no one else is responsible for your finances.", list:["Learn to read financial statements","Study basic investing","Understand taxes","Talk with people ahead of you"]},
 {e:"⚠️", h:"Read It With Caution", t:"The book contains no verifiable case studies, the characters are likely composites, and its advice on debt and real estate can be risky. Critics point out missing details. Treat it as motivation, not a manual."},
 {e:"🧩", h:"Learn From Mindset, Verify Facts", t:"The most useful takeaways are mindset ones: do not work only for money, track cash flow, and think about ownership. Check any specific strategy against other sources and your own situation before acting."},
 {e:"💡", h:"Cash Flow Thinking", t:"A simple tool from the book is tracking cash flow: what comes in from work and assets versus what goes out. Growing the inflow and keeping outflow modest is the core pattern. Summary in my own words; general education, not advice."}
], quiz:[
 {q:"How does Kiyosaki define an asset?", o:["Anything expensive","Something that puts money in your pocket","A big house"], a:1, w:"His definition is based on cash flow, not on price or status."},
 {q:"What is a notable criticism of the book?", o:["It is too short","Its stories and advice lack verifiable support","It has no opinions"], a:1, w:"Critics note unverifiable anecdotes and risky advice on debt."},
 {q:"What is the 'rat race' exit suggested?", o:["Win the lottery","Quit and travel","Build income-producing assets"], a:2, w:"The idea is for asset income to cover your living costs."},
 {q:"What is a safe way to use the book?", o:["As a mindset prompt, with verification","As a precise manual","Ignore all money books"], a:0, w:"Use its ideas for motivation and check specifics elsewhere."}
]},
{ id:"mo11", cat:"money", e:"📜", title:"The Intelligent Investor", sub:"Benjamin Graham's lasting rules", cards:[
 {e:"📚", h:"A Classic From 1949", t:"Benjamin Graham's book is a foundational text on value investing and was praised by Warren Buffett as the best investing book ever written. Its main focus is on temperament and discipline, not tricks.", stat:{n:"1949", l:"first publication of The Intelligent Investor"}},
 {e:"🎭", h:"Mr. Market", t:"Graham imagines a moody business partner who offers daily prices, sometimes cheerful and high, sometimes gloomy and low. You are free to ignore him. The market serves you; it does not instruct you. Use his mood swings, do not follow them."},
 {e:"🛡️", h:"Margin of Safety", t:"Buy only when the price is comfortably below what you estimate something is worth, leaving room for errors and bad luck. This cushion is the central concept of the book, and it applies to any financial decision."},
 {e:"🎰", h:"Investing vs Speculating", t:"Graham separates investing, which relies on thorough analysis, safety of principal, and adequate return, from speculating. Speculation is not forbidden, but keep it small and honestly labeled, using only money you can afford to lose."},
 {e:"⚖️", h:"Defensive vs Enterprising", t:"A defensive investor wants low effort and low risk and should diversify broadly. An enterprising investor spends serious time analyzing. Graham warned most people overestimate their ability to be the second kind.", list:["Diversify widely","Prefer financially sound companies","Avoid hot new issues","Be honest about your effort"]},
 {e:"🧊", h:"Your Worst Enemy Is You", t:"Graham stressed that investors' biggest risk is emotional: buying in euphoria, selling in fear. Writing rules in advance and following them when emotions run high is more valuable than any forecast."},
 {e:"🔮", h:"Do Not Forecast", t:"Predicting the market's next move is unreliable. Graham advised a simple policy, such as a fixed split between stocks and bonds, adjusted modestly, rather than betting on predictions. This remains practical today."},
 {e:"🌟", h:"Use It Wisely", t:"The book is dense and some specific formulas are dated. Read it for its mindset: patience, skepticism, and humility. Modern readers may prefer annotated editions. Summary in my own words; general education, not investment advice."}
], quiz:[
 {q:"What is Mr. Market?", o:["A famous broker","An emotional price-quoting partner","A government regulator"], a:1, w:"He is Graham's metaphor for the market's mood swings."},
 {q:"What is the margin of safety?", o:["A price comfortably below estimated value","A bank guarantee","An insurance policy"], a:0, w:"A buffer protects against mistakes and bad luck."},
 {q:"What did Graham see as the investor's biggest risk?", o:["Taxes","Inflation only","Their own emotions"], a:2, w:"He stressed that behavior mistakes outweigh most outside risks."},
 {q:"Who should diversify broadly and stay simple?", o:["The defensive investor","Only professionals","No one"], a:0, w:"A defensive investor wants low effort and low risk, so broad diversification fits."}
]},
{ id:"mo12", cat:"money", e:"🏡", title:"The Millionaire Next Door", sub:"What real wealth builders do", cards:[
 {e:"🔍", h:"Research Over Stereotypes", t:"Thomas Stanley and William Danko studied American millionaires and found they rarely fit the flashy image. Most lived in ordinary neighborhoods, drove modest cars, and built wealth through steady saving over decades."},
 {e:"💰", h:"Income Is Not Wealth", t:"A high income can be spent entirely. The authors found many high earners had little net worth, while many modest earners had substantial savings. Wealth is what you accumulate, not what you earn.", stat:{n:"Net worth", l:"is the key measure, not salary or lifestyle"}},
 {e:"🧮", h:"Prodigious Accumulators", t:"The authors introduced a rough formula: multiply your age by your pretax income and divide by ten to estimate expected net worth. Those far above are accumulators of wealth; far below are under-accumulators. It is a rough benchmark only."},
 {e:"🚗", h:"Frugality Drives Wealth", t:"Frugal habits like buying reasonable cars, living below your means, and budgeting were common among wealthy households. The principle is simple: spend less than you earn and invest the difference consistently over many years."},
 {e:"🏢", h:"Many Owned Businesses", t:"A large share of the millionaires studied were self-employed, often in unglamorous businesses like welding or pest control. Steady, boring ownership can generate high returns for those willing to work hard in less crowded fields."},
 {e:"👨‍👩‍👧", h:"Economic Outpatient Care", t:"The book warns that giving adult children regular financial handouts can reduce their independence and savings. Teaching skills and self-sufficiency, rather than steady gifts, tends to produce more capable, financially secure adults."},
 {e:"🧭", h:"Time, Energy, and Money", t:"The authors found that wealthy people invested more time planning finances and thought carefully about big purchases. Treating money as a skill you practice deliberately beats hoping for luck.", list:["Plan investments carefully","Budget regularly","Allocate time to finances","Think long-term"]},
 {e:"⚠️", h:"Caveats", t:"The research is from the 1990s and the US, and some figures are dated. Survivorship bias is possible. Still, its core message that modest living plus steady investing builds wealth remains sound. Summary in my own words; general education only."}
], quiz:[
 {q:"What did the authors find about typical millionaires?", o:["They were flashy spenders","Most lived modestly","They never saved"], a:1, w:"Many lived frugally in ordinary homes and cars."},
 {q:"What is the key measure of wealth in the book?", o:["Income","Brand of car","Net worth"], a:2, w:"Wealth is accumulated assets, not what you earn."},
 {q:"What do the authors warn about giving adult children?", o:["Education","Constant financial handouts","Advice"], a:1, w:"Regular handouts can reduce independence and savings."},
 {q:"What caveat applies to the research?", o:["Dated US data from the 1990s","It was done in space","It has no data"], a:0, w:"The study is old and American, so figures may not apply today."}
]},
{ id:"mo13", cat:"money", e:"🏘️", title:"Real Estate Basics", sub:"Renting, buying and what to weigh", cards:[
 {e:"🔑", h:"Buying vs Renting", t:"Neither is automatically better. Buying builds equity but adds maintenance, taxes, and less flexibility. Renting offers mobility and fewer surprises. Compare the true monthly cost of both, and how long you plan to stay."},
 {e:"📏", h:"The Five Percent Rule", t:"A quick check: multiply a home's price by about 5 percent, divide by twelve, and compare to rent. The 5 percent covers property tax, maintenance, and the cost of capital. If rent is lower, renting may be cheaper. It is a rough guide.", stat:{n:"5%", l:"of home value per year approximates unrecoverable ownership costs"}},
 {e:"💵", h:"Down Payment and Mortgage", t:"A larger down payment lowers your monthly payment and may avoid mortgage insurance. In the US, putting down 20 percent is a common benchmark, but many loans accept less. Do not drain your emergency fund to buy."},
 {e:"📉", h:"Total Cost of Ownership", t:"Budget beyond the mortgage: property tax, insurance, repairs, utilities, and possible association fees. A common guideline sets maintenance at about 1 percent of the home's value per year. Surprise repairs hurt most when unplanned.", list:["Mortgage interest","Property tax","Insurance","Maintenance, around 1% per year"]},
 {e:"🧱", h:"Location Matters Most", t:"You can renovate a house but not move it. Schools, job access, and neighborhood trends drive long-term value and resale. Research the area in person at different times of day before committing."},
 {e:"🧐", h:"Do Not Overextend", t:"A popular guideline says housing should stay under about 28 percent of gross income, and total debt under about 36 percent. Stretching beyond that leaves little room for surprises. Lenders may approve more than you can comfortably afford."},
 {e:"🏢", h:"Investment Property", t:"Rental properties can create cash flow, but they require time, vacancies are real, and repairs are costly. Calculate net rent after all expenses, not just the mortgage, and keep reserves. They are a business, not passive magic."},
 {e:"🔎", h:"Inspect and Compare", t:"Always get an independent home inspection and compare multiple mortgage offers, since small rate differences cost thousands over time. Never rely on a seller's agent alone. General education, not personal real estate or financial advice."}
], quiz:[
 {q:"What does the 5 percent rule estimate?", o:["Annual home appreciation","Unrecoverable annual ownership costs","Mortgage interest only"], a:1, w:"It approximates tax, maintenance and capital cost that do not build equity."},
 {q:"What is a common guideline for annual maintenance?", o:["About 1 percent of home value","Zero","50 percent of rent"], a:0, w:"Roughly 1 percent of value per year is a common budgeting figure."},
 {q:"Which is true about buying vs renting?", o:["Buying always wins","Renting always wins","Neither wins automatically"], a:2, w:"It depends on prices, rents, how long you stay and other factors."},
 {q:"Why get an independent inspection?", o:["To find defects before buying","To raise the price","It is required for rent"], a:0, w:"Inspections reveal costly problems before you commit."}
]},
{ id:"mo14", cat:"money", e:"🚨", title:"Avoiding Scams and Fraud", sub:"Spot the trap before it springs", cards:[
 {e:"🎣", h:"Scams Use Emotion", t:"Fraudsters create urgency, fear, or excitement so you act before thinking. Messages claiming your account is frozen or you have won a prize are designed to rush you. Slowing down is your best defense."},
 {e:"📞", h:"Impersonation Scams", t:"Callers or messages pretend to be your bank, a government agency, or tech support. Real organizations rarely demand immediate payment by gift card or crypto. Hang up and call the official number from the back of your card.", stat:{n:"$10B+", l:"reported US consumer fraud losses in 2023 per the FTC"}},
 {e:"💹", h:"Too Good to Be True", t:"Promises of guaranteed high returns with no risk are the hallmark of investment fraud. All real investments carry risk, and high returns carry high risk. Be skeptical of anyone pressuring you to invest quickly."},
 {e:"🔺", h:"Ponzi and Pyramid Schemes", t:"These pay earlier participants with money from new recruits, not real profits, and collapse when recruitment slows. If the main way to earn is recruiting others, or returns are suspiciously steady, walk away."},
 {e:"💔", h:"Romance and Pig Butchering", t:"Scammers build online relationships over weeks, then introduce an investment platform or an emergency. Never send money or crypto to someone you have not met in person. Reverse image searches can reveal fake profiles."},
 {e:"🎣", h:"Phishing Links", t:"Fake emails and texts mimic banks and delivery companies to steal logins. Do not click links in unexpected messages. Type the site's address yourself, and enable two-factor authentication on important accounts.", list:["Do not click unexpected links","Check sender addresses","Use two-factor authentication","Use a password manager"]},
 {e:"🔒", h:"Protect Your Information", t:"Never share one-time codes, passwords, or full Social Security-type numbers with anyone who contacts you first. Freezing your credit reports, which is free in the US, blocks most new-account fraud."},
 {e:"🆘", h:"If You Were Scammed", t:"Act quickly: contact your bank, change passwords, report to the relevant authority such as the FTC in the US, and freeze credit if needed. Do not feel shame, since scams fool smart people. Never pay a 'recovery' service upfront. General education only."}
], quiz:[
 {q:"What is a common scam tactic?", o:["Giving you time to decide","Creating urgency","Offering written contracts"], a:1, w:"Pressure and urgency are used to prevent clear thinking."},
 {q:"What should you do after an unexpected call claiming to be your bank?", o:["Give your PIN","Hang up and call the official number","Pay with gift cards"], a:1, w:"Verifying via a trusted number defeats impersonators."},
 {q:"What marks a likely investment fraud?", o:["Guaranteed high returns with no risk","Clear risk disclosure","Regulated broker"], a:0, w:"All real investments carry risk, so guarantees signal fraud."},
 {q:"What is a free defense against new-account fraud in the US?", o:["Sharing passwords","Freezing your credit reports","Paying a recovery fee"], a:1, w:"A credit freeze blocks lenders from opening accounts in your name."}
]},
{ id:"mo15", cat:"money", e:"🚀", title:"Entrepreneurship Fundamentals", sub:"Start small, test fast, stay solvent", cards:[
 {e:"🎯", h:"Start With a Real Problem", t:"Successful businesses solve a problem people already have and will pay to fix. Talk to potential customers before building anything. If ten people say they would not pay, believe them, no matter how much you love the idea."},
 {e:"🧪", h:"Validate Before Investing", t:"Test demand cheaply with a landing page, a pre-order, or a small pilot. A minimum viable product is the simplest version that tests whether customers care. Learning that early saves months and thousands of dollars."},
 {e:"📊", h:"Know Your Unit Economics", t:"Calculate what it costs to acquire a customer and how much profit they bring over time. If acquiring a customer costs more than they return, growth only increases losses. Margins decide whether a business can survive.", stat:{n:"~20%", l:"of US small businesses fail in year one, about half by year five (BLS)"}},
 {e:"💵", h:"Cash Flow Is Survival", t:"Profit on paper does not pay bills. Customers pay late, inventory ties up money, and costs arrive early. Track cash weekly and keep reserves of several months of expenses, because many viable firms die of cash shortage."},
 {e:"👥", h:"Choose Your Structure", t:"Common forms include sole proprietorship, partnership, LLC, and corporation, each with different liability and tax effects. An LLC can separate personal assets from business debts in many places. Consult a professional for your jurisdiction.", list:["Sole proprietorship","Partnership","LLC","Corporation"]},
 {e:"🌱", h:"Bootstrap When Possible", t:"Funding from your own savings and early revenue keeps you in control and forces discipline. Outside investors bring money and expectations of fast growth, which fits some businesses and harms others. Know the trade-off before you raise."},
 {e:"🛋️", h:"Keep Your Day Job at First", t:"Starting on the side reduces risk while you test the idea. Build a runway of savings, and set clear milestones for when to commit fully. Quitting early out of excitement is a frequent mistake."},
 {e:"📚", h:"Expect Setbacks", t:"Most ventures need pivots, and many fail. Treat failure as information, limit what you can lose, and keep personal and business finances separate. This is general education, not business, legal, or financial advice."}
], quiz:[
 {q:"What should you do before building a product?", o:["Talk to potential customers","Quit your job","Borrow heavily"], a:0, w:"Early conversations reveal whether the problem is real and paid for."},
 {q:"Why does cash flow matter?", o:["Paper profit pays bills","Many profitable firms fail from cash shortage","It only matters for big firms"], a:1, w:"Timing gaps between costs and payments can sink healthy businesses."},
 {q:"What does unit economics examine?", o:["Office size","Company logo","Cost to acquire a customer vs profit from them"], a:2, w:"If acquisition costs exceed returns, growth deepens losses."},
 {q:"What can an LLC help with in many places?", o:["Separating personal and business liability","Eliminating all taxes","Guaranteeing profit"], a:0, w:"It can shield personal assets from business debts, subject to local rules."}
]},
{ id:"mo16", cat:"money", e:"☂️", title:"Insurance and Protecting Wealth", sub:"Guard against the big losses", cards:[
 {e:"🌩️", h:"What Insurance Is For", t:"Insurance transfers rare, catastrophic costs to a company in exchange for steady premiums. Its goal is to protect you from losses you could not afford, not to cover small predictable expenses you can pay yourself."},
 {e:"🏥", h:"Health Coverage", t:"Medical bills are a leading cause of bankruptcy in the US. Understand your plan's deductible, copay, and out-of-pocket maximum, since the maximum caps your yearly risk. Check whether your doctors are in network before booking.", stat:{n:"Out-of-pocket max", l:"is the yearly cap on what you pay for covered care"}},
 {e:"👨‍👩‍👧", h:"Term Life Insurance", t:"If others depend on your income, term life insurance pays them if you die during the term. It is typically much cheaper than whole life products. Many advisors suggest coverage of ten to fifteen times annual income, depending on needs."},
 {e:"🩺", h:"Disability Coverage", t:"You are more likely to become unable to work than to die young, yet fewer people insure that risk. Disability insurance replaces part of your income. Check what your employer already provides before buying more."},
 {e:"🚗", h:"Auto and Home", t:"Carry liability coverage high enough to protect your assets, since lawsuits after accidents can be large. Raising deductibles lowers premiums, but only if you keep savings to pay them. Compare quotes yearly.", list:["Liability limits","Reasonable deductibles","Annual quote comparisons","Renters or homeowners policy"]},
 {e:"☔", h:"Umbrella Policies", t:"An umbrella policy adds extra liability coverage above auto and home limits, often for a modest cost per million dollars. It can make sense when your net worth or income exposes you to large lawsuits."},
 {e:"📉", h:"Inflation Is a Silent Risk", t:"Prices rise over time, so cash loses buying power. At 3 percent inflation, purchasing power halves in about 24 years. Holding some investments that can outpace inflation is a way to protect long-term wealth.", stat:{n:"3%", l:"yearly inflation halves purchasing power in roughly 24 years"}},
 {e:"📜", h:"Basic Estate Documents", t:"A simple will, beneficiary designations on accounts, and powers of attorney spare family confusion and cost. Review them after major life events like marriage or children. General education, not legal or insurance advice."}
], quiz:[
 {q:"What is insurance mainly meant to cover?", o:["Small predictable costs","Losses you could not afford","All shopping"], a:1, w:"Insurance suits rare, large losses, not routine expenses."},
 {q:"What does an out-of-pocket maximum do?", o:["Sets monthly premium","Caps your yearly covered costs","Raises your deductible"], a:1, w:"After you reach it, the plan pays covered costs for the rest of the year."},
 {q:"Who most needs term life insurance?", o:["Anyone with dependents relying on their income","Single people with no debt","Children"], a:0, w:"It replaces income for people who depend on yours."},
 {q:"What does inflation do to cash over time?", o:["Raises its buying power","Reduces its buying power","Has no effect"], a:1, w:"Rising prices mean the same cash buys less."}
]}
);
window.TIPS.push(
{cat:"money", e:"💡", h:"Automate your savings", t:"Set a transfer for payday. What you never see in your checking account, you never miss."},
{cat:"money", e:"💡", h:"Match first", t:"Contribute enough to get the full employer retirement match. It is the closest thing to free money."},
{cat:"money", e:"💡", h:"Wait 48 hours", t:"For any non-essential purchase over a set amount, wait two days. Many wants fade."},
{cat:"money", e:"💡", h:"Pay cards in full", t:"Credit card interest often exceeds typical investment returns. Pay the full statement balance every month."},
{cat:"money", e:"💡", h:"Check the fee", t:"A 1 percent fund fee sounds small but can consume a large slice of decades of growth."},
{cat:"money", e:"💡", h:"Net worth, not income", t:"Track what you keep, not what you earn. Net worth shows real progress."},
{cat:"money", e:"💡", h:"Emergency fund first", t:"Before investing, build a cushion of a few months of essential expenses."},
{cat:"money", e:"💡", h:"Start now", t:"Time in the market beats size of contributions. A small amount started early can outgrow a larger amount started late."},
{cat:"money", e:"💡", h:"Rule of 72", t:"Divide 72 by the annual return to estimate years to double your money."},
{cat:"money", e:"💡", h:"Negotiate every offer", t:"A polite counteroffer rarely loses the job and can raise pay for every future year."},
{cat:"money", e:"💡", h:"Look at total pay", t:"Compare offers by salary, bonus, retirement match, insurance, and flexibility, not the headline number alone."},
{cat:"money", e:"💡", h:"Do not announce your number", t:"Let the employer name the range first. Whoever names a number first often anchors the talk."},
{cat:"money", e:"💡", h:"Credit beats deduction", t:"A tax credit lowers your bill directly, while a deduction only lowers taxable income."},
{cat:"money", e:"💡", h:"Raises do not hurt", t:"Moving into a higher tax bracket only taxes the extra income at the higher rate."},
{cat:"money", e:"💡", h:"Keep tax records", t:"Store tax documents for at least three years in a folder sorted by year."},
{cat:"money", e:"💡", h:"Diversify widely", t:"Owning many companies through a broad fund spreads risk better than betting on a few."},
{cat:"money", e:"💡", h:"Do not time the market", t:"Nobody reliably predicts short-term moves. Regular investing beats trying to guess highs and lows."},
{cat:"money", e:"💡", h:"Rebalance yearly", t:"Check your asset mix once a year and bring it back to target if it has drifted."},
{cat:"money", e:"💡", h:"Stay put in crashes", t:"Selling in panic locks in losses. A written plan helps you stay calm when markets fall."},
{cat:"money", e:"💡", h:"Define enough", t:"Without a clear idea of enough, no amount feels sufficient. Decide what you want money for."},
{cat:"money", e:"💡", h:"Avoid lifestyle creep", t:"When income rises, save half of the raise before your spending adjusts."},
{cat:"money", e:"💡", h:"Wealth is unseen", t:"A fancy car shows spending. Real wealth is the money you did not spend."},
{cat:"money", e:"💡", h:"Use a sinking fund", t:"Save monthly for known annual costs like insurance and holidays, so they never surprise you."},
{cat:"money", e:"💡", h:"Avalanche or snowball", t:"Pay the highest rate first to save the most interest, or the smallest balance first for quick motivation."},
{cat:"money", e:"💡", h:"Keep utilization low", t:"Using under 30 percent of your credit limit helps your credit score."},
{cat:"money", e:"💡", h:"Pay on time", t:"Payment history is the biggest part of most credit scores. Set autopay for at least the minimum."},
{cat:"money", e:"💡", h:"Check credit reports", t:"Review your reports yearly for errors, which can raise your borrowing costs."},
{cat:"money", e:"💡", h:"No guaranteed returns", t:"Anyone promising high returns with no risk is selling fantasy or fraud."},
{cat:"money", e:"💡", h:"Verify the caller", t:"If a bank or agency calls unexpectedly, hang up and call the official number yourself."},
{cat:"money", e:"💡", h:"Gift cards are not payment", t:"Real agencies and companies do not demand gift cards, wire transfers, or crypto to fix a problem."},
{cat:"money", e:"💡", h:"Freeze your credit", t:"A credit freeze is free in the US and blocks most new-account fraud."},
{cat:"money", e:"💡", h:"Use two-factor login", t:"Turn on two-factor authentication for banking and email. It stops many account takeovers."},
{cat:"money", e:"💡", h:"Do not share codes", t:"Never read a one-time code to anyone who contacted you first."},
{cat:"money", e:"💡", h:"Margin of safety", t:"Leave room for error in every plan. Assume something will go wrong and still survive."},
{cat:"money", e:"💡", h:"Frugal is not cheap", t:"Spending less on things you do not value frees money for what you do."},
{cat:"money", e:"💡", h:"Total cost of owning", t:"A home or car costs far more than its price: insurance, tax, repairs, and upkeep."},
{cat:"money", e:"💡", h:"Compare mortgage offers", t:"A small rate difference over thirty years can cost thousands. Get several quotes."},
{cat:"money", e:"💡", h:"Get an inspection", t:"Hire an independent inspector before buying a home. It can reveal expensive defects."},
{cat:"money", e:"💡", h:"Housing share", t:"A common guideline keeps housing costs near 28 percent of gross income."},
{cat:"money", e:"💡", h:"Test before building", t:"Validate demand with a landing page or pre-order before spending months on a product."},
{cat:"money", e:"💡", h:"Cash flow is oxygen", t:"A business can show profit and still run out of cash. Track it weekly."},
{cat:"money", e:"💡", h:"Separate accounts", t:"Keep business and personal money in separate accounts from day one."},
{cat:"money", e:"💡", h:"Know unit economics", t:"If a customer costs more to win than they return, growing faster only increases your losses."},
{cat:"money", e:"💡", h:"Term over whole", t:"If you need life insurance for dependents, term policies are usually far cheaper than whole life."},
{cat:"money", e:"💡", h:"Know your maximum", t:"Your health plan's out-of-pocket maximum caps your yearly risk for covered care."},
{cat:"money", e:"💡", h:"Inflation erodes cash", t:"At 3 percent inflation, money loses half its buying power in about 24 years."},
{cat:"money", e:"💡", h:"Update beneficiaries", t:"Review who is named on accounts after marriage, children, or divorce."},
{cat:"money", e:"💡", h:"Luck is real", t:"Success and failure both involve luck. Be humble about wins and kind about others' losses."},
{cat:"money", e:"💡", h:"Time is the dividend", t:"The best thing money buys is control over your own time."},
{cat:"money", e:"💡", h:"Read the classics", t:"Books like The Intelligent Investor and The Psychology of Money teach behavior, which beats tactics."},
{cat:"money", e:"💡", h:"Question every guru", t:"Verify claims from any money book or influencer. Anecdotes are not evidence."},
{cat:"money", e:"💡", h:"Review monthly", t:"One short monthly money meeting beats daily worry. Compare plan to actual and fix one leak."},
{cat:"money", e:"💡", h:"Name your accounts", t:"Label savings by goal, such as car or travel. Named money is harder to raid."},
{cat:"money", e:"💡", h:"Save windfalls", t:"Put at least half of tax refunds and bonuses toward goals before spending."},
{cat:"money", e:"💡", h:"Cancel unused subscriptions", t:"Review your statements quarterly. Small recurring charges quietly add up to hundreds per year."},
{cat:"money", e:"💡", h:"Do not co-sign casually", t:"Co-signing makes you fully responsible for the debt if the borrower stops paying."},
{cat:"money", e:"💡", h:"Avoid rushing", t:"Urgency is the scammer's favorite tool. A legitimate offer will still be there tomorrow."},
{cat:"money", e:"💡", h:"Keep emergency cash separate", t:"Hold it in a different, insured account so you are not tempted to spend it."},
{cat:"money", e:"💡", h:"Teach kids early", t:"Let children handle small allowances and choices. Money skills are built by practice."},
{cat:"money", e:"💡", h:"Get professional help", t:"For complex taxes, estates, or business setup, a licensed professional can pay for themselves."}
);
